    """Given a string representing space separated lowercase letters, return a dictionary of the letter with the most repetition and containing the corresponding count. If several letters have the same occurrence, return all of them.

    Example:
    >>> print(histogram('a b c')) # {'a': 1, 'b': 1, 'c': 1}
    >>> print(histogram('a b b a')) # {'a': 2, 'b': 2}
    >>> print(histogram('a b c a b')) # {'a': 2, 'b': 2}
    >>> print(histogram('b b b b a')) # {'b': 4}
    >>> print(histogram('')) # {}

    """
    letter_count = {}
    words = test.split()

    for word in words:
        letters = set(word)
        for letter in letters:
            count = word.count(letter)
            if letter not in letter_count or (letter in letter_count and count > letter_count[letter]):
                letter_count[letter] = count

    # Filter out the entries with a count of 1, as we want to return all letters with their highest occurrence.
    max_occurrence = max(letter_count.values())
    result = {k: v for k, v in letter_count.items() if v == max_occurrence}

    return result

