def is_prime(num):
    """Check if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def fib_sequence():
    """Generate Fibonacci sequence."""
    fib_seq = [0, 1]

    while True:
        next_fib = fib_seq[-1] + fib_seq[-2]

        if is_prime(next_fib):
            yield next_fib

        else:
            continue

def prime_fib(n: int) -> int:
    """Return the n-th Fibonacci number that's also a prime."""

    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer.")

    fib_gen = fib_sequence()
    return next(itertools.islice(fib_gen, n-1, None)) # Offset by -1 because of zero indexing and islice's exclusive stop parameter
