def closest_integer(value):
    try:
        # Convert string to float for processing
        num = float(value)

        # Check if number is already an integer
        if abs(num - round(num)) < 0.0001:
            return int(round(num))

        # Determine the closest integers based on distance from zero
        lower_bound = int(math.floor(num))
        upper_bound = int(math.ceil(num))

        if num - lower_bound < upper_bound - num:
            return abs(lower_bound)  # Farthest from zero in the negative direction
        else:
            return abs(upper_bound)  # Farthest from zero in the positive direction

    except ValueError:
        raise ValueError("Input must be a numeric string.")

